const SKILLS_DIR = ".smol/skills";
const NAME_RE = /^[A-Za-z0-9_-]{1,40}$/;
const READ_CAP = 4000;
const SAVE_CAP = 8000;

function assertName(name: unknown): string {
  if (typeof name !== "string" || !NAME_RE.test(name.trim())) {
    throw new SandboxError(
      'skill name must be 1-40 letters, numbers, "-" or "_" (example: "login-debug").'
    );
  }
  return name.trim();
}

export function listSkills(root: string): string {
  let dir: string;
  try {
    dir = resolveInWorkspace(root, SKILLS_DIR);
  } catch {
    return "No skills saved yet.";
  }
  let names: string[];
  try {
    names = fs.readdirSync(dir).filter((f) => f.endsWith(".md")).map((f) => f.slice(0, -3));
  } catch {
    return "No skills saved yet.";
  }
  const valid = names.filter((n) => NAME_RE.test(n)).sort().slice(0, 50);
  if (!valid.length) return "No skills saved yet.";
  return `Skills (${valid.length}): ${valid.join(", ")}`;
}

export function readSkill(root: string, name: unknown): string {
  const clean = assertName(name);
  const abs = resolveInWorkspace(root, `${SKILLS_DIR}/${clean}.md`);
  if (!fs.existsSync(abs) || fs.statSync(abs).isDirectory()) {
    return `Error: no skill named "${clean}". Use skill {"action": "list"} to see saved skills.`;
  }
  const text = fs.readFileSync(abs, "utf8");
  return text.length > READ_CAP ? text.slice(0, READ_CAP) + "\n[skill truncated — keep skills short]" : text;
}

